<template>
  <main class="container reading page-section">
    <div v-if="loading" class="empty" aria-live="polite"><AppIcon name="book" :size="24" /><p>正在载入文章…</p></div>
    <div v-else-if="error" class="empty error-state" role="alert"><AppIcon name="info" :size="24" /><h1>{{ error }}</h1><RouterLink v-if="requiresLogin" class="button button-primary" :to="loginTarget">登录后继续阅读</RouterLink><RouterLink v-else class="button" to="/explore">返回探索</RouterLink></div>
    <article v-else-if="post">
      <div class="article-taxonomy" v-if="post.categories?.length || post.tags?.length"><RouterLink v-for="category in post.categories || []" :key="category.slug" class="taxonomy-link" :to="{path:'/explore',query:{category:category.slug}}">{{ category.name }}</RouterLink><RouterLink v-for="tag in post.tags || []" :key="tag.slug" class="taxonomy-link" :to="{path:'/explore',query:{tag:tag.slug}}">#{{ tag.name }}</RouterLink></div>
      <h1 class="page-title">{{ post.title }}</h1>
      <div class="byline"><UserAvatar :src="post.avatar_url || post.avatar_path" :name="post.username" :size="36" /><div><RouterLink :to="`/u/${post.blog_slug}`">{{ post.username }}</RouterLink><span>{{ date(post.published_at) }} · {{ post.reading_minutes || 1 }} 分钟阅读</span></div></div>
      <img v-if="post.cover_image" class="cover" :src="post.cover_image" alt="文章封面"><p v-if="post.excerpt" class="lead">{{ post.excerpt }}</p>
      <div class="article" v-html="html"></div>
      <div class="article-actions" aria-label="文章操作">
        <button class="button" :class="{selected:liked}" type="button" :disabled="actionPending.like" :aria-pressed="liked" @click="toggleLike"><AppIcon name="heart" :size="17" />{{ actionPending.like ? '处理中' : liked ? '已喜欢' : '喜欢' }} <span>{{ post.like_count }}</span></button>
        <button class="button" :class="{selected:bookmarked}" type="button" :disabled="actionPending.bookmark || bookmarked" :aria-pressed="bookmarked" @click="bookmark"><AppIcon name="bookmark" :size="17" />{{ actionPending.bookmark ? '处理中' : bookmarked ? '已收藏' : '收藏' }}</button>
        <button class="button button-ghost" type="button" :disabled="actionPending.report || reported" @click="report"><AppIcon name="shield" :size="17" />{{ reported ? '已举报' : actionPending.report ? '提交中' : '举报' }}</button>
      </div>
      <p v-if="actionMessage" class="action-status" :class="{error:actionError}" role="status">{{ actionMessage }}</p>
      <section class="comments" aria-labelledby="comments-title"><div class="comments-heading"><h2 id="comments-title">评论 <span>{{ comments.length }}</span></h2><p v-if="!canComment" class="muted">作者已关闭评论。</p></div>
        <form v-if="loggedIn&&canComment" class="comment-form" @submit.prevent="submitComment"><label for="comment-content">写评论</label><textarea id="comment-content" v-model="commentText" :disabled="commentPending" maxlength="5000" placeholder="写下你的想法…"></textarea><div><span class="muted">{{ commentText.length }} / 5000</span><button class="button button-primary" :disabled="commentPending || !commentText.trim()">{{ commentPending ? '提交中…' : '发表评论' }}</button></div></form>
        <p v-else-if="canComment" class="login-prompt muted">登录后参与讨论。<RouterLink :to="loginTarget">登录</RouterLink></p>
        <p v-if="commentError" class="error comment-error" role="alert">{{ commentError }}</p>
        <div v-if="commentsLoading" class="comments-loading muted">正在载入评论…</div>
        <div v-else-if="!comments.length" class="comment-empty muted">暂时还没有评论。</div>
        <div v-else class="comment-list"><article v-for="comment in rootComments" :key="comment.id" class="comment"><CommentItem :comment="comment" :replies="repliesFor(comment.id)" :logged-in="loggedIn" :current-user-id="currentUserId" :pending-delete-id="pendingDeleteId ?? undefined" @reply="startReply" @remove="removeComment" /><form v-if="replyTo===comment.id&&loggedIn" class="reply-form" @submit.prevent="submitComment"><label :for="`reply-${comment.id}`">回复 {{ comment.username }}</label><textarea :id="`reply-${comment.id}`" v-model="commentText" :disabled="commentPending" maxlength="5000" placeholder="回复这条评论"></textarea><div><button class="button button-ghost" type="button" :disabled="commentPending" @click="cancelReply">取消</button><button class="button button-primary" :disabled="commentPending || !commentText.trim()">{{ commentPending ? '发送中…' : '发送回复' }}</button></div></form></article></div>
      </section>
    </article>
  </main>
</template>

<script setup lang="ts">
import { computed, defineComponent, h, onMounted, ref, watch } from 'vue'
import { useRoute, RouterLink } from 'vue-router'
import { marked } from 'marked'
import DOMPurify from 'dompurify'
import http from '@/services/http'
import AppIcon from '@/components/AppIcon.vue'
import UserAvatar from '@/components/UserAvatar.vue'

type TaxonomyItem={name:string;slug:string}
type Post={id:number;title:string;username:string;blog_slug:string;avatar_url?:string|null;avatar_path?:string|null;published_at?:string|null;reading_minutes?:number;cover_image?:string|null;excerpt?:string|null;content_markdown?:string|null;like_count:number;bookmark_count?:number;categories?:TaxonomyItem[];tags?:TaxonomyItem[];viewer_liked?:boolean;viewer_bookmarked?:boolean}
type Comment={id:number;parent_id?:number|null;author_id?:number|null;username:string;content:string;created_at:string;deleted_at?:string|null}

const route=useRoute(), post=ref<Post>(), comments=ref<Comment[]>([]), loading=ref(true), commentsLoading=ref(false), error=ref(''), commentText=ref(''), replyTo=ref<number|null>(null), canComment=ref(false), actionMessage=ref(''), actionError=ref(false), commentError=ref(''), commentPending=ref(false), pendingDeleteId=ref<number|null>(null), liked=ref(false), bookmarked=ref(false), reported=ref(false)
const actionPending=ref({like:false,bookmark:false,report:false})
const loggedIn=localStorage.getItem('isLoggedIn')==='true'
const currentUserId=Number(JSON.parse(localStorage.getItem('userInfo')||'{}').id)||0
const html=computed(()=>DOMPurify.sanitize(String(marked.parse(post.value?.content_markdown||''))))
const requiresLogin=computed(()=>error.value.includes('登录'))
const loginTarget=computed(()=>({path:'/login',query:{redirect:route.fullPath}}))
const rootComments=computed(()=>comments.value.filter(comment=>!comment.parent_id))
const date=(value:string|null|undefined)=>{if(!value)return '刚刚';const parsed=new Date(value);return Number.isNaN(parsed.getTime())?'刚刚':new Intl.DateTimeFormat('zh-CN',{dateStyle:'medium'}).format(parsed)}
const shareConfig=()=>route.query.share?{params:{share:String(route.query.share)}}:{}
function repliesFor(parentId:number){return comments.value.filter(comment=>comment.parent_id===parentId)}
function setActionMessage(message:string,isError=false){actionMessage.value=message;actionError.value=isError}
function login(){window.location.assign(`/login?redirect=${encodeURIComponent(route.fullPath)}`)}
async function loadComments(){if(!post.value)return;commentsLoading.value=true;try{comments.value=(await http.get(`/api/posts/${post.value.id}/comments`,shareConfig())).data.items||[]}catch(e:any){commentError.value=e.response?.data?.error?.message||'评论暂时无法载入。'}finally{commentsLoading.value=false}}
async function load(){loading.value=true;error.value='';commentError.value='';actionMessage.value='';try{const response=await http.get(`/api/public/posts/${route.params.slug}`,shareConfig());post.value=response.data.post;canComment.value=Boolean(response.data.canComment);liked.value=Boolean(post.value?.viewer_liked);bookmarked.value=Boolean(post.value?.viewer_bookmarked);await loadComments()}catch(e:any){error.value=e.response?.data?.error?.message||'文章不可用'}finally{loading.value=false}}
async function toggleLike(){if(!loggedIn)return login();if(!post.value||actionPending.value.like)return;actionPending.value.like=true;setActionMessage('');const wasLiked=liked.value;const oldCount=post.value.like_count;try{if(wasLiked){await http.delete(`/api/posts/${post.value.id}/like`,shareConfig());liked.value=false;post.value.like_count=Math.max(0,oldCount-1);setActionMessage('已取消喜欢。')}else{await http.post(`/api/posts/${post.value.id}/like`,{},shareConfig());liked.value=true;if(typeof post.value.viewer_liked==='boolean')post.value.like_count=oldCount+1;setActionMessage('已喜欢这篇文章。')}}catch(e:any){liked.value=wasLiked;post.value.like_count=oldCount;setActionMessage(e.response?.data?.error?.message||'操作未完成，请稍后重试。',true)}finally{actionPending.value.like=false}}
async function bookmark(){if(!loggedIn)return login();if(!post.value||actionPending.value.bookmark||bookmarked.value)return;actionPending.value.bookmark=true;setActionMessage('');try{await http.post(`/api/posts/${post.value.id}/bookmark`,{},shareConfig());bookmarked.value=true;setActionMessage('已收藏到你的工作台。')}catch(e:any){setActionMessage(e.response?.data?.error?.message||'收藏未完成，请稍后重试。',true)}finally{actionPending.value.bookmark=false}}
async function report(){if(!loggedIn)return login();if(!post.value||actionPending.value.report||reported.value)return;actionPending.value.report=true;setActionMessage('');try{await http.post('/api/reports',{postId:post.value.id,reason:'其他'},shareConfig());reported.value=true;setActionMessage('举报已提交，我们会按规则处理。')}catch(e:any){setActionMessage(e.response?.data?.error?.message||'举报未提交，请稍后重试。',true)}finally{actionPending.value.report=false}}
function startReply(comment:Comment){if(!loggedIn)return login();replyTo.value=comment.id;commentText.value='';commentError.value=''}
function cancelReply(){replyTo.value=null;commentText.value=''}
async function submitComment(){if(!post.value||!commentText.value.trim()||commentPending.value)return;commentPending.value=true;commentError.value='';try{await http.post(`/api/posts/${post.value.id}/comments`,{content:commentText.value.trim(),parentId:replyTo.value},shareConfig());commentText.value='';replyTo.value=null;await loadComments();setActionMessage('评论已发布。')}catch(e:any){commentError.value=e.response?.data?.error?.message||'评论未发布，请稍后重试。'}finally{commentPending.value=false}}
async function removeComment(id:number){if(!confirm('确定删除这条评论？此操作无法撤销。'))return;pendingDeleteId.value=id;commentError.value='';try{await http.delete(`/api/comments/${id}`);await loadComments();setActionMessage('评论已删除。')}catch(e:any){commentError.value=e.response?.data?.error?.message||'删除未完成，请稍后重试。'}finally{pendingDeleteId.value=null}}

const CommentItem=defineComponent({name:'CommentItem',props:{comment:{type:Object as()=>Comment,required:true},replies:{type:Array as()=>Comment[],required:true},loggedIn:{type:Boolean,required:true},currentUserId:{type:Number,required:true},pendingDeleteId:{type:Number,default:null}},emits:['reply','remove'],setup(props,{emit}){return()=>h('div',{class:'comment-content'},[h('div',{class:'comment-meta'},[h('b',props.comment.username),h('span',{class:'muted'},` · ${date(props.comment.created_at)}`)]),h('p',props.comment.content),h('div',{class:'comment-actions'},[props.loggedIn&&!props.comment.parent_id?h('button',{class:'reply',type:'button',onClick:()=>emit('reply',props.comment)},'回复'):null,props.comment.author_id===props.currentUserId?h('button',{class:'reply delete',type:'button',disabled:props.pendingDeleteId===props.comment.id,onClick:()=>emit('remove',props.comment.id)},props.pendingDeleteId===props.comment.id?'删除中…':'删除'):null]),props.replies.length?h('div',{class:'reply-list'},props.replies.map(reply=>h('div',{class:'reply-item',key:reply.id},[h('div',{class:'comment-meta'},[h('b',reply.username),h('span',{class:'muted'},` · ${date(reply.created_at)}`)]),h('p',reply.content),reply.author_id===props.currentUserId?h('button',{class:'reply delete',type:'button',disabled:props.pendingDeleteId===reply.id,onClick:()=>emit('remove',reply.id)},props.pendingDeleteId===reply.id?'删除中…':'删除'):null]))):null])}})
watch(()=>route.fullPath,load)
onMounted(load)
</script>

<style scoped>
.reading{max-width:820px}.page-title{font-size:clamp(2.1rem,6vw,3.5rem);line-height:1.16}.article-taxonomy{display:flex;flex-wrap:wrap;gap:var(--space-1);margin-bottom:var(--space-3)}.taxonomy-link{padding:2px var(--space-2);border:1px solid var(--border);border-radius:999px;color:var(--muted);font-size:.8rem;text-decoration:none}.taxonomy-link:hover{border-color:var(--accent);color:var(--accent)}.byline{display:flex;align-items:center;gap:var(--space-2);color:var(--muted);font-size:.9rem}.byline>div{display:grid;gap:2px}.byline span{color:var(--subtle)}.byline a{color:var(--accent);font-weight:700}.cover{width:100%;max-height:440px;object-fit:cover;border-radius:var(--radius);margin:var(--space-6) 0}.lead{font-size:1.18rem;color:var(--muted);border-left:3px solid var(--accent);padding-left:var(--space-4)}.article{font-size:1.05rem;line-height:1.85}.article :deep(img){max-width:100%;height:auto}.article :deep(pre){overflow:auto;padding:var(--space-4);background:var(--surface);border:1px solid var(--border);border-radius:var(--radius-sm)}.article :deep(blockquote){margin-left:0;padding-left:var(--space-4);border-left:3px solid var(--border);color:var(--muted)}.article-actions{display:flex;flex-wrap:wrap;gap:var(--space-2);border-top:1px solid var(--border);padding-top:var(--space-5);margin-top:var(--space-6)}.article-actions .selected{border-color:var(--accent);background:var(--accent-soft);color:var(--accent-strong)}.action-status{margin:var(--space-2) 0 0;color:var(--muted);font-size:.9rem}.action-status.error{color:var(--danger)}.comments{margin-top:var(--space-8)}.comments-heading{display:flex;align-items:baseline;justify-content:space-between;gap:var(--space-3)}.comments h2{margin:0}.comments h2 span{color:var(--subtle);font-size:1rem;font-weight:500}.comment-form,.reply-form{display:grid;gap:var(--space-2);margin-top:var(--space-4)}.comment-form label,.reply-form label{font-size:.92rem;font-weight:700}.comment-form textarea,.reply-form textarea{width:100%;min-height:110px;padding:var(--space-3);color:var(--text);background:var(--surface-raised);border:1px solid var(--border);border-radius:var(--radius-sm);resize:vertical}.comment-form textarea:focus,.reply-form textarea:focus{border-color:var(--accent);outline:0;box-shadow:0 0 0 3px var(--accent-soft)}.comment-form>div,.reply-form>div{display:flex;align-items:center;justify-content:space-between;gap:var(--space-2)}.comment-form>div .muted{font-size:.8rem}.login-prompt a{color:var(--accent);font-weight:700}.comment-error{margin-top:var(--space-3)}.comments-loading,.comment-empty{padding:var(--space-5) 0}.comment-list{margin-top:var(--space-4)}.comment{padding:var(--space-4) 0;border-bottom:1px solid var(--border)}.comment-content p,.reply-item p{white-space:pre-wrap}.comment-meta{font-size:.92rem}.reply{border:0;padding:0;background:transparent;color:var(--accent);font:inherit;font-size:.86rem}.reply:hover{text-decoration:underline}.reply.delete{color:var(--danger);margin-left:var(--space-3)}.comment-actions{min-height:20px}.reply-list{display:grid;gap:var(--space-3);margin-top:var(--space-3);padding-left:var(--space-4);border-left:2px solid var(--border)}.reply-item{font-size:.94rem}.reply-form{margin-top:var(--space-3);padding:var(--space-3);border:1px solid var(--border);border-radius:var(--radius-sm);background:var(--surface)}.reply-form textarea{min-height:82px}.empty{display:grid;justify-items:center;gap:var(--space-2)}.empty h1,.empty p{margin:0}.error-state{border-style:solid}@media(max-width:640px){.article-actions .button{flex:1}.comments-heading{align-items:start;flex-direction:column;gap:var(--space-1)}.comment-form>div,.reply-form>div{align-items:stretch;flex-direction:column}.comment-form>div .button,.reply-form>div .button{width:100%}}
</style>
